mapper.select:
select link_id, user_id, link_type, token_hash, expire_time, used_time, revoked_time, create_by, create_time
from sys_account_link
where token_hash = #{tokenHash}

mapper.update:
update sys_account_link
set revoked_time = #{now}
where user_id = #{userId}
  and used_time is null
  and revoked_time is null

update sys_account_link
set used_time = #{now}
where link_id = #{linkId}
  and used_time is null
  and revoked_time is null
  and expire_time > #{now}
